CREATE TABLE propriedades (id BIGSERIAL PRIMARY KEY,nome VARCHAR(120) NOT NULL,area_hectares NUMERIC(12,4) NOT NULL CHECK(area_hectares>0),localizacao VARCHAR(240) NOT NULL,responsavel VARCHAR(120) NOT NULL,ativa BOOLEAN NOT NULL DEFAULT TRUE,criada_em TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uk_propriedade_nome_local UNIQUE(nome,localizacao));
CREATE TABLE cargos (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),nome VARCHAR(100) NOT NULL,atribuicoes VARCHAR(500) NOT NULL,custo_hora_referencia NUMERIC(12,2) NOT NULL CHECK(custo_hora_referencia>=0),CONSTRAINT uk_cargo_propriedade_nome UNIQUE(propriedade_id,nome));
CREATE TABLE funcionarios (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),cargo_id BIGINT NOT NULL REFERENCES cargos(id),nome VARCHAR(140) NOT NULL,equipe VARCHAR(100),horario_trabalho VARCHAR(100) NOT NULL,custo_hora_individual NUMERIC(12,2) CHECK(custo_hora_individual>=0),custo_hora_efetivo NUMERIC(12,2) NOT NULL CHECK(custo_hora_efetivo>=0),ativo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE usuarios (id BIGSERIAL PRIMARY KEY,funcionario_id BIGINT NOT NULL UNIQUE REFERENCES funcionarios(id),login VARCHAR(80) NOT NULL UNIQUE,senha_hash VARCHAR(100) NOT NULL,perfil VARCHAR(30) NOT NULL CHECK(perfil IN ('PROPRIETARIO','GERENTE_CAMPO','OPERADOR')),ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE talhoes (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),identificacao VARCHAR(80) NOT NULL,area_hectares NUMERIC(12,4) NOT NULL CHECK(area_hectares>0),localizacao VARCHAR(240),descricao_limites VARCHAR(1000),criado_em TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uk_talhao_propriedade_identificacao UNIQUE(propriedade_id,identificacao));
CREATE TABLE pastagens (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),identificacao VARCHAR(80) NOT NULL,descricao VARCHAR(1000) NOT NULL,ativa BOOLEAN NOT NULL DEFAULT TRUE,CONSTRAINT uk_pastagem_propriedade_identificacao UNIQUE(propriedade_id,identificacao));
CREATE TABLE lotes (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),pastagem_id BIGINT NOT NULL REFERENCES pastagens(id),identificacao VARCHAR(80) NOT NULL,data_formacao DATE NOT NULL,ativo BOOLEAN NOT NULL DEFAULT TRUE,CONSTRAINT uk_lote_propriedade_identificacao UNIQUE(propriedade_id,identificacao));
CREATE TABLE animais (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT NOT NULL REFERENCES propriedades(id),lote_atual_id BIGINT NOT NULL REFERENCES lotes(id),identificacao VARCHAR(80) NOT NULL,especie VARCHAR(60) NOT NULL,raca VARCHAR(80),peso_inicial_kg NUMERIC(10,3) NOT NULL CHECK(peso_inicial_kg>0),idade_meses INTEGER CHECK(idade_meses>=0),data_entrada DATE NOT NULL,observacoes VARCHAR(500),ativo BOOLEAN NOT NULL DEFAULT TRUE,CONSTRAINT uk_animal_propriedade_identificacao UNIQUE(propriedade_id,identificacao));
CREATE TABLE vinculos_animal_lote (id BIGSERIAL PRIMARY KEY,animal_id BIGINT NOT NULL REFERENCES animais(id),lote_id BIGINT NOT NULL REFERENCES lotes(id),data_inicio DATE NOT NULL,data_fim DATE,CHECK(data_fim IS NULL OR data_fim>=data_inicio));
CREATE UNIQUE INDEX uk_vinculo_animal_aberto ON vinculos_animal_lote(animal_id) WHERE data_fim IS NULL;
CREATE TABLE auditorias (id BIGSERIAL PRIMARY KEY,propriedade_id BIGINT,autor VARCHAR(80),tipo_evento VARCHAR(30) NOT NULL,entidade VARCHAR(80) NOT NULL,registro_id BIGINT,ocorrido_em TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_auditoria_propriedade_data ON auditorias(propriedade_id,ocorrido_em DESC);
